+bool Core::emitBatteryLevelNotification(int level, int previousLevel, const QString &udi)
+{
+    const auto isLow = [](int batteryLevel) {
+        return batteryLevel == Solid::Battery::LowBatteryLevel || batteryLevel == Solid::Battery::CriticalBatteryLevel;
+    };
+
+    // Show the notification just once on each normal->low transition
+    if (!isLow(level) || isLow(previousLevel)) {
+        return false;
+    }
+
+    return emitPeripheralBatteryNotification(udi, -1 /* the level has no exact percentage */);
+}
+
+bool Core::emitPeripheralBatteryNotification(const QString &udi, int percent)
+{
+    using namespace Solid;
+    Device device(udi);
+    Battery *b = qobject_cast<Battery *>(device.asDeviceInterface(DeviceInterface::Battery));
+    if (!b) {
+        return false;
+    }
+
+    // If you leave the device out of reach or it has not been initialized yet,
+    // it won't be "there" and can report an empty or unknown percentage.
+    if (!b->isPresent() || b->chargePercent() <= 0) {
+        return false;
+    }
+
+    // Bluetooth devices don't report charge state, so it's "NoCharge" in all cases for them
+    if (b->chargeState() != Battery::Discharging && b->chargeState() != Battery::NoCharge) {
+        return false;
+    }
+
+    QString name = device.product();
+    if (!device.vendor().isEmpty()) {
+        name = i18nc("%1 is vendor name, %2 is product name", "%1 %2", device.vendor(), device.product());
+    }
+
+    QString title = percent < 0 ? i18nc("The battery in an external device", "Device Battery Low")
+                                : i18nc("The battery in an external device", "Device Battery Low (%1% Remaining)", percent);
+    QString msg;
+    if (b->isRechargeable()) {
+        msg = i18nc("Placeholder is device name", "The battery in “%1” is running low. Please recharge the battery.", name);
+    } else {
+        msg = i18nc("Placeholder is device name", "The battery in “%1” is running low.", name);
+    }
+    QString icon = QStringLiteral("battery-caution");
+
+    switch (b->type()) {
+    case Battery::MouseBattery:
+        title = percent < 0 ? i18n("Mouse Battery Low") : i18n("Mouse Battery Low (%1% Remaining)", percent);
+        icon = QStringLiteral("input-mouse");
+        break;
+    case Battery::KeyboardBattery:
+        title = percent < 0 ? i18n("Keyboard Battery Low") : i18n("Keyboard Battery Low (%1% Remaining)", percent);
+        icon = QStringLiteral("input-keyboard");
+        break;
+    case Battery::HeadphoneBattery:
+        icon = QStringLiteral("audio-headphones-battery");
+        break;
+    case Battery::HeadsetBattery:
+        icon = QStringLiteral("audio-headset-battery");
+        break;
+    case Battery::PhoneBattery:
+        title = percent < 0 ? i18n("Phone Battery Low") : i18n("Phone Battery Low (%1% Remaining)", percent);
+        icon = QStringLiteral("phone-battery");
+        break;
+    case Battery::BluetoothBattery:
+        title = percent < 0 ? i18n("Bluetooth Device Battery Low") : i18n("Bluetooth Device Battery Low (%1% Remaining)", percent);
+        icon = QStringLiteral("preferences-system-bluetooth");
+        break;
+    default:
+        break;
+    }
+
+    emitNotification(QStringLiteral("lowperipheralbattery"), title, msg, icon);
+    return true;
+}
+
 void Core::handleLowBattery(int percent)
 {
     if (m_lowBatteryNotification) {
@@ -769,6 +800,31 @@ void Core::onBatteryChargePercentChanged(int percent, const QString &udi)
     }
 }

+void Core::onBatteryLevelChanged(int level, const QString &udi)
+{
+    if (!m_peripheralBatteriesPercent.contains(udi)) {
+        return;
+    }
+
+    if (level == Solid::Battery::NoBatteryLevel) {
+        m_peripheralBatteriesLevel.remove(udi);
+        return;
+    }
+
+    const int previousLevel = m_peripheralBatteriesLevel.value(udi, Solid::Battery::UnknownBatteryLevel);
+    if (level == Solid::Battery::UnknownBatteryLevel) {
+        // Devices report an unknown level while they are asleep or out of reach, so keep the last known one
+        m_peripheralBatteriesLevel[udi] = previousLevel;
+        return;
+    }
+
+    m_peripheralBatteriesLevel[udi] = level;
+
+    if (m_notificationsReady) {
+        emitBatteryLevelNotification(level, previousLevel, udi);
+    }
+}
+
 void Core::onBatteryChargeStateChanged(int state, const QString &udi)
 {
     if (!m_batteriesCharged.contains(udi)) {
@@ -977,6 +1033,11 @@ void Core::onServiceRegistered(const QString &service)
             needsRefresh = true;
         }
     }
+    for (auto it = m_peripheralBatteriesLevel.constBegin(), end = m_peripheralBatteriesLevel.constEnd(); it != end; ++it) {
+        if (emitBatteryLevelNotification(it.value() /*level*/, Solid::Battery::UnknownBatteryLevel, it.key() /*udi*/)) {
+            needsRefresh = true;
+        }
+    }

     // need to refresh status to prevent the notification from showing again when charge percentage changes
     if (needsRefresh) {
