+Solid::Battery::BatteryLevel Battery::batteryLevel() const
+{
+    // New in upower v0.99.5.
+    const QVariant batteryLevel = m_device.data()->prop(QStringLiteral("BatteryLevel"));
+    if (!batteryLevel.isValid()) {
+        return Solid::Battery::NoBatteryLevel;
+    }
+
+    switch (static_cast<UpDeviceLevel>(batteryLevel.toUInt())) {
+    case UP_DEVICE_LEVEL_UNKNOWN:
+        return Solid::Battery::UnknownBatteryLevel;
+    case UP_DEVICE_LEVEL_CRITICAL:
+        return Solid::Battery::CriticalBatteryLevel;
+    case UP_DEVICE_LEVEL_LOW:
+        return Solid::Battery::LowBatteryLevel;
+    case UP_DEVICE_LEVEL_NORMAL:
+        return Solid::Battery::NormalBatteryLevel;
+    case UP_DEVICE_LEVEL_HIGH:
+        return Solid::Battery::HighBatteryLevel;
+    case UP_DEVICE_LEVEL_FULL:
+        return Solid::Battery::FullBatteryLevel;
+    case UP_DEVICE_LEVEL_NONE:
+    case UP_DEVICE_LEVEL_DISCHARGING: // only used for WarningLevel
+    case UP_DEVICE_LEVEL_ACTION: // only used for WarningLevel
+    case UP_DEVICE_LEVEL_LAST:
+        break;
+    }
+    return Solid::Battery::NoBatteryLevel;
+}
